import zlib

extension gzip {
  /*
   * compress the given file: create a corresponding .gz file and remove the
   * original.
   */
  func file_compress(_ file : FilePath) -> UInt? {
    //   int in;
    //    int out;
    //    off_t size, in_size;

    //    struct stat isb, osb;
    //    const suffixes_t *suff;

    guard let inx = try? FileDescriptor.open(file, .readOnly) else {
      maybe_warn("can't open \(file)")
      return nil
    }

    defer { try? inx.close() }

    //    bzero(&isb, sizeof(isb));
    guard let isb = try? FileMetadata(for: inx) else {
      maybe_warn("couldn't stat: \(file)")
      return nil
    }

    r.infile = file
    r.infile_total = isb.size

    if !options.cflag {
      if isb.links > 1 && !options.fflag {
        maybe_warnx("\(file) has \(isb.links-1) other link\(isb.links == 2 ? "" : "s") -- skipping")
        return nil
      }

      if !options.fflag, let hs = check_suffix(file) {
        maybe_warnx("\(file) already has \(hs) suffix -- unchanged")
        return nil
      }

      /* Add (usually) .gz to filename */
      let outfile = FilePath("\(file)\(options.suffix)")
      r.outfile = outfile

      if !check_outfile(outfile) {
        return nil
      }
    }

    var out : FileDescriptor
    let outfile = r.outfile!
    let size = UInt(0)


    defer {
      maybe_warnx("leaving original \(file)")
      unlink(outfile.string)
    }

    if (!options.cflag) {
      guard let o = try? FileDescriptor.open(outfile, .writeOnly, options: [.create, .exclusiveCreate], permissions: FilePermissions(rawValue: 0o0600) ) else {
        maybe_warn("could not create output: \(outfile)")
        fclose(stdin);
        return nil
      }
      out = o
      remove_file = outfile;
    } else {
      out = FileDescriptor.standardOutput
    }

    defer {
      if let _ = try? out.close() {
      } else {
        maybe_warn("couldn't close output");
      }
    }

    guard let (size, in_size) = gz_compress(inx, out, basename(file.string), isb.lastWrite) else {
      return nil
    }

    /*
     * If there was an error, in_size will be -1.
     * If we compressed to stdout, just return the size.
     * Otherwise stat the file and check it is the correct size.
     * We only blow away the file if we can stat the output and it
     * has the expected size.
     */

    // FIXME: returning optional pairs means I can't test in_size separately from size
    // need to fix all the returns -- maybe use throw?
/*    if options.cflag {
      return in_size == -1 ? -1 : size;
    }
*/
    
    guard let osb = try? FileMetadata(for: out) else {
      maybe_warn("couldn't stat: \(outfile)")
      return size
    }

    if (osb.size != size) {
      maybe_warnx("output file: \(outfile) wrong size (\(osb.size) != \(size)), deleting")
      return size
    }

    fcopyfile(inx.rawValue, out.rawValue, nil, copyfile_flags_t(COPYFILE_ACL | COPYFILE_XATTR))
    clear_type_and_creator(out);

    copymodes(out, isb, outfile);
    remove_file = nil

    try? inx.close()
    guard let _ = try? out.close() else {
      maybe_warn("couldn't close output")
      // FIXME: is this right?
      return nil
    }

    /* output is good, ok to delete input */
    unlink_input(file, isb)
    return size
  }

  /* uncompress the given file and remove the original */
  func file_uncompress(_ file : FilePath) -> UInt? {
    /*    struct stat isb, osb;
     off_t size;
     ssize_t rbytes;
     unsigned char fourbytes[4];
     enum filetype method;
     int fd, ofd, zfd = -1;
     int error;
     size_t in_size;

     ssize_t rv;
     time_t timestamp = 0;
     */

    /* gather the old name info */

    var size : UInt? = nil

    guard let fd = try? FileDescriptor.open(file, .readOnly) else {
      maybe_warn("can't open \(file)")
      return nil
    }

    defer { try? fd.close() }

    guard var isb = try? FileMetadata(for: fd) else {
      maybe_warn("can't stat \(file)")
      return nil
    }

    var in_size = isb.filetype == .regular ? isb.size : 0
    r.infile = file
    r.infile_total = in_size

    var outfile = file
    if check_suffix(outfile) == nil && !(options.cflag || options.lflag) {
      maybe_warnx("\(file): unknown suffix -- ignored")
      return nil
    }

    let fourbytes = try? fd.readUpToCount(4)
    guard fourbytes?.count ?? -1 == 4, let fourbytes else {
      /* we don't want to fail here. */

      if options.fflag {
        return nil
      }
      if fourbytes == nil {
        maybe_warn("can't read \(file)")
      }
      else {
        maybe_warnx("\(file): unexpected end of file")
        return nil
      }
      return nil
    }

    r.infile_current += 4

    let method = file_gettype(fourbytes);

    if !options.fflag && method == .UNKNOWN {
      maybe_warnx("\(file): not in gzip format")
      return nil
    }

    var timestamp : DateTime?

    if method == .GZIP && options.Nflag {
      //      unsigned char ts[4];  /* timestamp */

      var ts : [UInt8] = [0, 0, 0, 0]
      guard let four = try? fd.read(fromAbsoluteOffset: Int64(GZIP_TIMESTAMP), into:
                                      withUnsafeMutablePointer(to: &ts) {p in UnsafeMutableRawBufferPointer(start: p, count: 4)
      }) else {
        if !options.fflag {
          maybe_warn("can't read \(file.string)")
          return nil
        }
        // FIXME: is this right?
        return nil
      }

      if four < GZIP_TIMESTAMP {
        maybe_warnx("\(file): unexpected end of file")
        return nil
      }

      r.infile_current += UInt(four)
      timestamp = DateTime(le32dec(ts))

      if 0 != (Int(fourbytes[3]) & ORIG_NAME) {
        var name = Array(repeating: UInt8(0), count: Int(PATH_MAX) + 1)

        let nc = name.count
        guard let rbytes = try? fd.read(fromAbsoluteOffset: Int64(GZIP_ORIGNAME), into: withUnsafeMutablePointer(to: &name) {p in
          UnsafeMutableRawBufferPointer(start: p, count: nc-1) } ) else {
          maybe_warn("can't read \(file)")
          return nil
        }

        let nn = String(cString: name).prefix(rbytes)

        if !nn.isEmpty {
          let nf = nn.split(separator: "/").last! // strip saved directory name

          /* preserve original directory name */
          let dp = file.string.replacing(/\/[^\/]*$/, with: "/")
          r.outfile =  FilePath(dp + nf)
        }
      }
    }

    let _ = try? fd.seek(offset: 0, from: .start)

    if !options.cflag || options.lflag {
      if isb.links > 1 && !options.lflag && !options.fflag {
        maybe_warnx("\(file) has \(isb.links-1) other links -- skipping")
        return nil
      }
      if !options.nflag, let timestamp {
        isb.lastWrite = timestamp
      }
      if !check_outfile(outfile) {
        return nil
      }
    }

    var zfd : FileDescriptor? = nil

    if options.cflag {
      zfd = FileDescriptor.standardOutput
    }
    else if options.lflag {
      zfd = nil
    }
    else {
      guard let zz = try? FileDescriptor.open(outfile, .writeOnly, options: [.create, .exclusiveCreate], permissions: .init(rawValue:  0o0600)) else {
        maybe_warn("can't open \(outfile)")
        return nil
      }

      if zz == FileDescriptor.standardOutput {
        /* We won't close STDOUT_FILENO later... */
        zfd = try? zz.duplicate()
        try? FileDescriptor.standardOutput.close()
      }
      remove_file = outfile
    }

    defer {
      if let rf = remove_file, !options.cflag {
        unlink(rf.string)
      }
      remove_file = nil
    }

    defer {
      if zfd != FileDescriptor.standardOutput {
        try? zfd?.close()
      }
    }

    switch method {

      case .BZIP2:
        /* XXX */
        if options.lflag {
          maybe_warnx("no -l with bzip2 files");
          return nil
        }

        if let k = Bzip2(self).unbzip2(fd, zfd!, []) {
          size = k.0
        } else {
          return nil
        }

      case .Z:

        /* XXX */
        if options.lflag {
          maybe_warnx("no -l with Lempel-Ziv files");
          return nil
        }

        let inx = s_zstate.zdopen(self, fd) /* else {
          maybe_warn("zdopen for read: \(file)")
          return nil
        }*/

        guard let out = try? zfd!.duplicate() else {
          maybe_warn("fdopen for write: \(outfile)")
          _ = inx.zclose()
          return nil
        }

        guard let (size, _) = inx.zuncompress(out, []) else {
          return nil
        }

        /* need to fclose() if ferror() is true... */

        // FIXME: I failed to detect any errors on read
        //let error = ferror(inx);
        let error = 0
        if 0 != error || 0 != inx.zclose() {
          if 0 != error {
            maybe_warn("failed infile")
          }
          else {
            maybe_warn("failed infile fclose")
          }
          try? out.close()
          return nil
        }
        guard let _ = try? out.close() else {
          maybe_warn("failed outfile close");
          return nil
        }

      case .PACK:
        if options.lflag {
          maybe_warnx("no -l with packed files")
          return nil
        }

        guard let (size, _) = unpack_descriptor_t(self).unpack(fd, zfd!, []) else {
          return nil
        }

      case .XZ:
        let uuu = Unxz(self)
        if options.lflag {
          size = uuu.unxz_len(fd);
          if (!options.tflag) {
            print_list_out(in_size, size!, file);
            return nil
          }
        } else {
          guard let k = uuu.unxz(fd, zfd!, []) else {
            return nil
          }
          (size, _) = k
        }

      case .LZ:
        if options.lflag {
          maybe_warnx("no -l with lzip files");
          return nil
        }
        guard let (size, _) = lz.unlz(fd, zfd!, []) else {
          return nil
        }
        break;

      case .UNKNOWN:
        if (options.lflag) {
          maybe_warnx("no -l for unknown filetypes")
          return nil
        }
        size = cat_fd([], FileDescriptor.standardInput)

      default:
        if options.lflag {
          print_list(fd, in_size, outfile, isb.lastWrite)
          if !options.tflag {
            return nil  /* XXX */
          }
        }

        if let k = gz_uncompress(fd, zfd!, [], file) {
          size = k.0
        } else {
          return nil
        }
    }

    guard let size else {
      maybe_warnx("\(file.string): uncompress failed")
      return nil
    }

    /* if testing, or we uncompressed to stdout, this is all we need */

    if options.tflag {
      return size
    }

    /* if we are uncompressing to stdin, don't remove the file. */
    if options.cflag {
      return size;
    }

    /*
     * if we create a file...
     */
    /*
     * if we can't stat the file don't remove the file.
     */

    guard let ofd = try? FileDescriptor.open(outfile, .readWrite) else {
      maybe_warn("couldn't open (leaving original): \(outfile)")
      return nil
    }

    defer { try? ofd.close() }

    guard let osb = try? FileMetadata(for: ofd) else {
      maybe_warn("couldn't stat (leaving original): \(outfile)")
      return nil
    }
    if osb.size != size {
      maybe_warnx("stat gave different size: \(size)) != \(osb.size) (leaving original)")
      return nil
    }

    copymodes(ofd, isb, outfile)
    unlink_input(file, isb)
    return size
  }

  func check_siginfo() {
    var stderr = FileDescriptor.standardError
    if !print_info.load(ordering: .relaxed) {
      return
    }
    if let inf = r.infile {
      if 0 != r.infile_total {
        let pcent = Int((100 * r.infile_current) / r.infile_total)
        print("\(inf): done \(r.infile_current)/\(r.infile_total) bytes \(pcent)%", to: &stderr)
      } else {
        print("\(inf): done \(r.infile_current) bytes", to: &stderr)
      }
    }
    print_info.store(false, ordering: .relaxed)
  }

  func cat_fd(_ prepend : [UInt8], _ fd : FileDescriptor) -> UInt? {

    var in_tot = UInt(prepend.count)
    guard let w = try? FileDescriptor.standardOutput.write(prepend) else {
      maybe_warn("write to stdout");
      return nil
    }
    while true {
      guard let buf = try? fd.readUpToCount(Self.BUFLEN) else {
        maybe_warn("read from fd \(fd.rawValue)")
        break;
      }

      if buf.isEmpty {
        break;
      }

      r.infile_current += UInt(buf.count)

      guard let rv = try? FileDescriptor.standardOutput.write(buf) else {
        maybe_warn("write to stdout");
        break;
      }
      in_tot += UInt(rv)
    }

    return in_tot;
  }
}

